/* @lc app=leetcode id=3891 lang=kotlin */ class Solution { fun minIncrease(nums: IntArray): Long = nums.size.let { n -> nums.indices.map { i -> if (i == 0 || i == n - 1) 0L else maxOf(0L, maxOf(nums[i - 1], nums[i + 1]).toLong() + 1 - nums[i]) }.let { c -> if (n % 2 == 1) (1..n - 2 step 2).sumOf { c[it] } else ((n - 2) / 2).let { m -> (1..m).runningFold(0L) { s, j -> s + c[2 * j - 1] }.let { po -> (1..m).runningFold(0L) { s, j -> s + c[2 * j] }.let { ev -> (0..m).minOf { t -> po[t] + ev[m] - ev[t] } } } } } } }